INSERT INTO `san_shop_news` (`id`, `name`, `news_date`, `description`, `description_short`, `picture_url_1`, `picture_url_2`, `picture_url_3`, `show_on_frontpage`, `active`) VALUES
(1,	'Dankort betaling',	'2015-06-04',	'<p><span style=\"color: #000000;\">Cloud Routers partnerportal kan tage imod betaling med Dankort, s&aring;ledes at vores kunder kan afgive online ordrer, med et Dankort fra&nbsp;dags dato.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\">L&aelig;s mere om fordele ved betaling med Dankort p&aring;</span> <a href=\"http://www.dankort.dk/\" target=\"_blank\"><span style=\"color: #3366ff;\"><span style=\"color: #3366ff;\">Nets</span></span></a>.</p>',	'Cloud Routers partnerportal har fået Dankort betalingsmulighed.',	'',	'https://shankar.sitecare.org/billeder/pages/dankort.png',	'',	0,	1),
(7,	'Professionelle Site-survey ydelser',	'2016-07-01',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Cloud Router introducerer resultats-orienteret Site-survey ydelser, inden for WiFi netv&aelig;rk og radiolink. Site-survey ydelsen kan v&aelig;re en effektiv l&oslash;sning til vores forhandlerpartnere og slutkunder. Virksomheder og institutioner kan betragte Cloud Router som en uvildig&nbsp;r&aring;dgiver, til at identificere problemstillingerne p&aring; en eksisterende&nbsp;l&oslash;sning eller for at kortl&aelig;gge de n&oslash;dvendige elementer i forbindelse med en ny implementering.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\"><br /></span></p>',	'Cloud Router introducerer professionelle Site-survey ydelser inden for WLAN og radiolink.<br> Klik for at læse mere.',	'',	'',	'https://shankar.sitecare.org/docs/news/2016/Site-survey.jpg',	0,	1),
(11,	'Cloud Router på FDA messen 2016',	'2016-11-30',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Cloud Router var en af de 22 udstillere p&aring; FDA messen&nbsp;den 4. og 5. november 2016. Efter to sp&aelig;ndende dage sluttede FDA messen 2016 i Kolding p&aring; Scandic hotel. Det har v&aelig;ret rigtig interessant for Cloud Router at v&aelig;re med, da vores budskab om fremtidens WiFi til private husstande og tr&aring;dl&oslash;se backbone l&oslash;sninger til udbydere blev m&oslash;dt op med store interesse fra antenneforeningerne.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\"><br /></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Udover vi har haft talt med mange interesserede bes&oslash;gere p&aring; vores stand, havde vi muligheden for at udvide vores viden om de forskellige kommunikationsformer inden for kabel-tv l&oslash;sninger.</span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\"><strong>Om FDA</strong></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><span style=\"color: #000000;\">Forenede Danske Antenneanl&aelig;g er en interesseorganisation for 195 brugerejede antenneanl&aelig;g over hele landet. Antenneanl&aelig;ggene har tilsammen ca. 190.000 tilslutninger og repr&aelig;senterer dermed ca. 500.000 tv-seere. Antenneanl&aelig;ggene leverer tv- og radiosignaler, internet og IP-telefoni til anten&shy;neanl&aelig;ggenes medlemme. For mere information&nbsp;bes&oslash;g FDA p&aring;</span>&nbsp;<a title=\"Bes&oslash;g FDA\" href=\"http://www.fda.dk/\" target=\"_blank\">www.fda.dk</a></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><br /></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\">Her kan der ses nogle stemningsbilleder fra&nbsp;udstillingen.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><br /></span></p>',	'Efter to spændende dage sluttede FDA messen 2016 i Kolding på Scandic hotel. Det har været rigtig interessant for Cloud Router at være med, da budskabet om fremtidens WiFi til private husstande og trådløse backbone løsninger blev mødt op med store interesse fra antenneforeningerne.',	'',	'https://shankar.sitecare.org/docs/news/2016/FDA_2016_01.jpg',	'https://shankar.sitecare.org/docs/news/2016/FDA_2016_02.jpg',	0,	1),
(12,	'Infinity WiFi hos Antenneforeningerne',	'2016-12-01',	'<p><strong><strong>Pressemeddelelse</strong>: Infinity WiFi hos Antenneforeningerne - <span style=\"color: #0000ff;\"><a title=\"Infinity WiFi hos Antenneforeningerne\" href=\"https://drive.google.com/open?id=12GMrXlimCRyOka7vvQKbvFG8J8XAZ7-f\" target=\"_blank\"><span style=\"color: #0000ff;\">Download PDF</span></a></span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: justify;\">Panther Applications og Cloud Router har etableret et strategisk og teknisk samarbejde, hvilket betyder at antenneforeningerne i Danmark st&aring;r st&aelig;rkere med unikke&nbsp;tr&aring;dl&oslash;se l&oslash;sninger i fremtiden.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Panther Applications udvikler og leverer det administrative system Panther Admin, som benyttes af over 70 antenne- og bredb&aring;ndsforeninger i Danmark. Panther Admin benyttes af foreningerne til administration, afregning, provisionering og overv&aring;gning af netv&aelig;rksudstyr, internet- og TV abonnementer. Panther Admin system kan nu ogs&aring; administrere Infinity Access punkter fra LigoWave.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Behov</strong><br />Udfordringen for bredb&aring;ndsforeninger er, at tr&aring;dl&oslash;se radioer og tilh&oslash;rende firmware i traditionelt CPE udstyr, herunder kabelmodems og fiberbokse, typisk er af lav kvalitet og yderligere installeres uhensigtsm&aelig;ssigt i forhold til tr&aring;dl&oslash;s udbredelse. Dette giver ustabilitet og store supportm&aelig;ssige udfordringer, da st&oslash;rste dele af alt udstyr i dag tilsluttes tr&aring;dl&oslash;st. Mange bredb&aring;ndsforeninger har benyttet WiFi Access punkter fra Ubiquiti og Linksys, som delvis har afhjulpet problemet. Dette udstyr kr&aelig;ver imidlertid en controller eller remote adgang til den enkelte private husstande for fejlfinding og tilpasning, hvilket ender ofte ude i mange teknikker timer og til sidst en d&aring;rlig forretning for alle parter.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>L&oslash;sning</strong><br />I dag kan antenneforeninger levere Infinity WiFi Access punkter til private husstande og administrere disse fra deres Panther Admin system, lige som de allerede administrerer deres kabel modemmer. Infinity Access punkter er integreret i Panther Admin system b&aring;de for provisioning og monitorering. Konfiguration og indstillinger er gjort tilg&aelig;ngelig for teknikker og supporter i Panther Admin administrationsgr&aelig;nsefladen, og for medlemmerne / kunderne via selvbetjeningsportalen.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Nogle af landets f&oslash;rende antenneforeninger har allerede valgt NFT-2AC Infinity Access punkt til deres medlemmer, siden offentligg&oslash;relsen af Panther Admin integration under FDA messen 2016 i Kolding. Cloud Router og Panther Applications vil forsat arbejde p&aring; at udvide funktioner p&aring; Infinity WiFi igennem Panther Admin. Infinity Access punkter tilsluttes bag p&aring; medlemmernes eksisterende CPE udstyr, og kan herefter indstilles og overv&aring;ges direkte i Panther Admin, eller medlemmet kan overv&aring;ge og &aelig;ndre indstillinger via selvbetjening.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Om Panther Applications</strong><br />Panther Applications leverer Panther Admin til antenneforeninger som er et administrationsv&aelig;rkt&oslash;j der samler alle elementer / tr&aring;de i det at drive en antenneforening. Ved at samle alle elementer I en enkelt administrativ l&oslash;sning opn&aring;r vores kunder store fordele og muligg&oslash;r automatisering af en lang r&aelig;kke dagligdagsopgaver. Med Panther Admin kan antenneforeninger med stor &oslash;konomisk fordel drives selvst&aelig;ndigt - Det siger vi, og det beviser vores referencer. Med Panther Admin giver det hele lidt bedre mening, b&aring;de for forening og medlemmer. For yderligere information bes&oslash;g venligst www.pantherapplications.com og&nbsp;<a href=\"http://www.pantheradmin.dk\">www.pantheradmin.dk</a></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong><br /></strong></p>\r\n<p style=\"text-align: justify;\"><strong>Om LigoWave Infinity WiFi</strong><br />LigoWave historie begyndte i 2007 som et team dedikeret til at udvikle kvalitets tr&aring;dl&oslash;st kommunikationsudstyr til de bredb&aring;nd og enterprise markedssegmenter. LigoWave engagement i fremragende har ikke vaklet gennem &aring;rene og har givet LigoWave mulighed for at vokse ind i et internationalt m&aelig;rke i dag. LigoWave har udvidet produkter til at opfylde alle markeder, herunder WiFi, punkt-til-punkt for backbone applikationer og punkt-til-multipunkt data distribution. Med en urokkelig vilje til at overskride grundl&aelig;ggende ydelse, har LigoWave udviklet propriet&aelig;r protokoller, der bryder gr&aelig;nserne for standard WiFi og punkt-til-punkt l&oslash;sninger fra konkurrenterne. L&aelig;s mere p&aring; www.ligowave.com</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<div style=\"text-align: justify;\"><br /><strong>Om Cloud Router</strong><br />Cloud Router er en vidensbaseret netv&aelig;rksdistribut&oslash;r med spidskompetence inden for tr&aring;dl&oslash;s datakommunikation. Vores drivkraft i Cloud Router er et langvarigt samarbejde baseret p&aring; viden og innovation. Vi stiller vores ressourcer til r&aring;dighed for samarbejdspartnere, som &oslash;nsker at benytte os til at levere innovative netv&aelig;rksl&oslash;sninger p&aring; markedet. Flere f&oslash;rende IT-forhandlere, installat&oslash;rer og serviceudbydere har p&aring; baggrund af vores ekspertise og markedsviden valgt at samarbejde med os. Som en moderne virksomhed f&oslash;ler vi ansvar for at v&aelig;re med til at udvikle og fremtidssikre vores samfund. Det g&oslash;r vi ved at have fokus p&aring; innovative og omkostningseffektive l&oslash;sninger inden for vores kerneomr&aring;de som er tr&aring;dl&oslash;s <span>datakommunikation.</span></div>\r\n<div><span><br /></span></div>\r\n<div><span><br /></span></div>',	'Panther Applications og Cloud Router har etableret et strategisk og teknisk samarbejde, hvilket betyder at antenneforeningerne i Danmark står stærkere med unikke trådløse løsninger i fremtiden.',	'https://shankar.sitecare.org/docs/news/2017/Panther_logo.png',	'https://shankar.sitecare.org/docs/news/2017/Panther_admin.png',	'',	0,	1),
(13,	'Introducering af Hardware replacement',	'2017-04-03',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Cloud Routers Hardware replacement tilf&oslash;jer produkterne en SLA, i form af teknisk r&aring;dgivning, udvidet garanti og kortere behandlingstid. Forhandlere kan anvende&nbsp;Hardware replacement&nbsp;til at bygge SLA og serviceaftaler p&aring; leverede netv&aelig;rksl&oslash;sninger. Derved sikres en professionel&nbsp;implementering og fremtidssikret drift hos slutkunden.</span></p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\">&bull; For yderligere information, se vores</span>&nbsp;<span style=\"color: #0000ff;\"><a title=\"Hardware replacement\" href=\"https://drive.google.com/file/d/1D5ileoJz1prVvaL7KNEprLIFil-_HibX/view\" target=\"_blank\"><span style=\"color: #0000ff;\">Hardware replacement&nbsp;<span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">brochure</span></span></span></a></span></p>\r\n<p><span><span style=\"color: #000000;\">&bull; For teknisk assistance, RMA m.m. bes&oslash;g siden&nbsp;Service&nbsp;p&aring;</span>&nbsp;</span><span style=\"color: #0000ff;\"><a href=\"http://www.cloudrouter.dk/service\"><span style=\"color: #0000ff;\">http://www.cloudrouter.dk/service</span></a></span></p>',	'Cloud Routers Hardware replacement tilføjer produkterne en SLA, i form af teknisk rådgivning, udvidet garanti og kortere behandlingstid. Læs videre...',	'https://shankar.sitecare.org/docs/news/2017/Hardware-support_banner.png',	'',	'',	0,	1),
(14,	'Ny ledelse hos Cloud Router',	'2017-07-10',	'<p><strong><span style=\"color: #000000;\">Pressemeddelelse: Ny ledelse hos Cloud Router&nbsp;-</span> <span style=\"color: #0000ff;\"><a title=\"Ny ledelse hos Cloud Router PDF\" href=\"https://drive.google.com/open?id=1gac2hSUXrT2d4kUpKC0HS6IDo9jkVpKq\" target=\"_blank\"><span style=\"color: #0000ff;\">Hent PDF</span></a></span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Fra 01. juli 2017 har Cloud Router f&aring;et ny ledelsesstruktur. En ny bestyrelse, der skal h&aring;ndtere det overordnede ansvar for virksomhedens strategiske og finansielle ledelse. Det sker som f&oslash;lge af virksomhedens fokus p&aring; levering af kommunikationsudstyr til internet- og mobiludbydere. Administrerende direkt&oslash;r Shangar Kumaran, er fortsat ansvarlig for drift og produktstrategi - og for tilpasningen af virksomhedens salgsaktiviteter.</span></p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\">Bestyrelsesformand Erik Niels Juul udtaler om den nye ledelsesstruktur:</span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">&rdquo;Cloud Router har v&aelig;ret en innovativ virksomhed siden sin opstart. Cloud Router har til stadighed introduceret nye og unikke l&oslash;sningsmuligheder inden for tr&aring;dl&oslash;se l&oslash;sninger til antenneforeninger.</span></p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Vi har f&aring;et samarbejde med en af verdens f&oslash;rende radiolink producenter. Dermed kan Cloud Router v&aelig;re attraktiv for det danske prim&aelig;re kundesegment, som er internetudbydere. Vi vil s&aelig;tte endnu mere fart i vores forretningsudvikling. Derfor har vi fundet det &oslash;nskeligt at &aelig;ndre vores ledelsesstruktur.</span></p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">En af selskabets ambitioner er snarligt, at omdanne Cloud Router til et aktieselskab. Dette vil v&aelig;re muligt indenfor de kommende m&aring;neder, samtidig vil vi kunne indg&aring; aftaler med investorer. Jeg gl&aelig;der mig over at v&aelig;re en del af en ambiti&oslash;s virksomhed med et st&aelig;rkt fokus p&aring; at levere en 100% alternativ l&oslash;sning til koax og fiber nedgravninger.&rdquo;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\">Cloud Routers forretningsorden for bestyrelsen er offentlig tilg&aelig;ngelig og kan hentes</span> <span style=\"color: #0000ff;\"><a title=\"Forretningsorden Cloud router ApS\" href=\"http://www.cloudrouter.dk/docs/profile/CR_forretningsorden.pdf\" target=\"_blank\"><span style=\"color: #0000ff;\">her</span></a></span><a title=\"Forretningsorden Cloud router ApS\" href=\"http://www.cloudrouter.dk/docs/profile/CR_forretningsorden.pdf\" target=\"_blank\">.</a></p>\r\n<p><br /><span style=\"color: #000000;\">Cloud Router ApS</span><br /><span style=\"color: #000000;\">Svendborgvej 226</span><br /><span style=\"color: #000000;\">DK-5260 Odense S</span></p>',	'Fra 01. juli 2017 har Cloud Router fået ny ledelsesstruktur. En ny bestyrelse, der skal håndtere det overordnede ansvar for virksomhedens strategiske og finansielle ledelse. Læs videre...',	'',	'',	'',	0,	1),
(15,	'Cloud Router bliver Ceragon distributør',	'2017-09-20',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\"><strong>Pressemeddelelse</strong>:&nbsp;Cloud Router bliver Ceragon Networks distribut&oslash;r i Danmark -&nbsp;</span><a title=\"Cloud Router bliver Ceragon distribut&oslash;r\" href=\"https://drive.google.com/open?id=1N_8BL2aOmF7CXdz6fb2ZBxqCcC-uz26U\" target=\"_blank\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">PDF udgave</span></span></a></p>\r\n<p style=\"text-align: justify;\"><a title=\"Cloud Router bliver Ceragon distribut&oslash;r\" href=\"https://drive.google.com/open?id=1N_8BL2aOmF7CXdz6fb2ZBxqCcC-uz26U\" target=\"_blank\"><span style=\"color: #000000;\"><br /></span></a></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">I forbindelse med &oslash;get fokus p&aring; digitalisering af vores samfund, kan kommunerne ved hj&aelig;lp af Cloud Routers l&oslash;sninger etablere h&oslash;jhastighedsinternetforbindelser til tyndt befolkede omr&aring;der, for en 1/10 del af omkostningerne til nedgravede l&oslash;sninger.<br /><br /></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">&rdquo;Cloud Router har leveret 5 - 6GHz tr&aring;dl&oslash;se backbone l&oslash;sninger til antenneforeninger, udbydere og installat&oslash;rer, som er omkostningseffektive sammenlignet med Koax og Ethernet kabelgravninger. Cloud Router kan nu tilbyde en omfattende portef&oslash;lje af 7 - 80GHz radiolinks fra Ceragon, som er den ideelle erstatning til fibergravninger og fiberforl&aelig;ngelser.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #000000;\">Ceragon er verdensf&oslash;rende inden for mikrob&oslash;lge og millimeter-wave radiolinks til full-duplex dataforbindelser, CCTV backbone og Gigabit backup forbindelser. Vi vil fremadrettet arbejde p&aring; at Ceragon radiolinks bliver det fortrukne valg hos energiselskaber, udbydere og mobile operat&oslash;rer, n&aring;r der skal etableres en backbone, med samme responstid som fiber.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #000000;\">Vi er stolte af at Ceragon har identificeret vores kompetence og markedskendskab inden for tr&aring;dl&oslash;se kommunikationsl&oslash;sninger, og ser frem til at skabe et v&aelig;rdifuldt resultat for begge parter.&rdquo;</span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong><span style=\"color: #000000;\">Om Ceragon</span></strong><br /><span style=\"color: #000000;\">Det b&oslash;rsnoterede Ceragon er f&oslash;rende producent af radiolinks, som benyttes af mobile operat&oslash;rer, det offentlige, olieindustrien og professionelle virksomheder p&aring; verdensplan. Ceragon ser det som sin vigtigste opgave at g&oslash;re datakommunikation mere produktiv og b&aelig;redygtig. Det sker i kraft af et h&oslash;jt kompetenceniveau, unik teknologi samt en globaliseret organisation. Virksomheden har leveret over 900.000 professionelle radiolinks p&aring; verdensplan. L&aelig;s mere p&aring; <span style=\"color: #0000ff;\"><a href=\"http://www.ceragon.com\"><span style=\"color: #0000ff;\">www.ceragon.com</span></a></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><strong><span style=\"color: #000000;\">Om Cloud Router</span></strong><br /><span style=\"color: #000000;\">Cloud Router er en vidensbaseret netv&aelig;rksdistribut&oslash;r med spidskompetence inden for tr&aring;dl&oslash;s datakommunikation. Vores drivkraft i Cloud Router er et langvarigt samarbejde baseret p&aring; viden. Som en moderne virksomhed f&oslash;ler vi et ansvar for at v&aelig;re med til at udvikle og fremtidssikre vores samfund. Det g&oslash;r vi ved at have fokus p&aring; bedre og omkostningseffektive l&oslash;sninger inden for vores kerneomr&aring;de som er tr&aring;dl&oslash;s datakommunikation. L&aelig;s mere p&aring; <span style=\"color: #0000ff;\"><a href=\"http://www.cloudrouter.dk\"><span style=\"color: #0000ff;\">www.cloudrouter.dk</span></a></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">&nbsp;</span></p>',	'I forbindelse med øget fokus på digitalisering af vores samfund, kan kommunerne ved hjælp af Cloud Routers løsninger etablere højhastighedsinternetforbindelser til tyndt befolkede områder, for en 1/10 del af omkostningerne til nedgravede løsninger. Læs videre..',	'https://shankar.sitecare.org/docs/news/2017/Ceragon_solution.png',	'',	'',	0,	1),
(16,	'Cloud Router og LigoWave styrker samarbejdet',	'2018-11-20',	'<p style=\"text-align: justify;\"><span style=\"color: #0000ff;\"><a title=\"Download som PDF udgave\" href=\"https://drive.google.com/file/d/1BVTQKvzcQaDbkqkqJCKwOaDHCbvheruM/view\" target=\"_blank\"><span style=\"color: #0000ff;\"><strong>Hent som PDF udgave</strong></span></a></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><strong><br />Cloud Router og LigoWave er nu klar med et nyt partnerprogram og med et udvidet lager til forhandlere i Danmark. Det overordnede f&aelig;lles m&aring;l er, at vores forhandlere i Danmark skal opn&aring; endnu st&oslash;rre succes med at s&aelig;lge, installere og servicere LigoWave produkter.</strong></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\">Vi er glade for at kunne bidrage og v&aelig;re med til at introducere det nye partnerprogram, som har fokus p&aring; konkurrencedygtige priser, forretningsekspertise og udvidelse af markedet. Hos Cloud Router er vi sikker p&aring; at LigoWaves partnerprogram vil give Cloud Router og vores v&aelig;rdsatte forhandlere / installat&oslash;rer gensidig salgsv&aelig;kst p&aring; markedet. I dag leverer Cloud Router produkter og serviceydelser til en r&aelig;kke IT-forhandlere, el-installat&oslash;rer, CCTV-installat&oslash;rer og antenneforeninger. Vi har sammen med LigoWave dannet et nyt team, som udvider vores forretningsomr&aring;de indenfor WiFi og radiok&aelig;de til ogs&aring; at d&aelig;kke byggepladser, trafiksektor og industriomr&aring;der.</span></p>\r\n<p><br /><br /></p>\r\n<p><span style=\"color: #333333;\"><strong>Udvidelse af lageret</strong></span><br /><span style=\"color: #333333;\">Vi har udvidet vores lager med en st&oslash;rre m&aelig;ngde af udvalgte produkter.<br />Dermed kan vores kunder indenfor en eller to hverdage, f&aring; tilsendt de mest efterspurgte produkter.<br /><br /></span></p>\r\n<p><span style=\"color: #333333;\"><strong>Str&oslash;mlinet prisstruktur til forhandlere</strong></span><br /><span style=\"color: #333333;\">Prisstrukturen er gjort enkel med en vejledende salgsprisliste p&aring; produkterne. </span><br /><span style=\"color: #333333;\">Dertil kommer der to rabatsatser for forhandlere: standard og autoriseret.<br /><br /></span></p>\r\n<p><span style=\"color: #333333;\"><strong>Projekt (Deal) registrering med mulighed for SPA priser</strong></span><br /><span style=\"color: #333333;\">Cloud Router, som er den officielle LigoWave distribut&oslash;r i Danmark, kan tilbyde vores autoriserede forhandlere s&aelig;rlige (SPA) priser p&aring; produkter til registrerede projekter.<br /><br /></span></p>\r\n<p><span style=\"color: #333333;\"><strong>Aktiviteter og v&aelig;rkt&oslash;jer der udvider forretningsekspertisen</strong></span><br /><span style=\"color: #333333;\">Med LigoWaves Partner Program kan vi arbejde side om side med vores autoriserede forhandlere og derved udvikle nye forretningsmuligheder med unikke og innovative tr&aring;dl&oslash;se l&oslash;sninger til kunder i Danmark. Vi afholder tre vigtige aktiviteter: &Aring;bent hus-arrangementer, hands-on workshops og certificerings tr&aelig;ning, for derved&nbsp;at styrke samarbejdet, og samtidig &oslash;ge ekspertisen hos alle parter.</span></p>\r\n<p style=\"text-align: justify;\"><br /><br /><span style=\"color: #333333;\">&rdquo;LigoWave kan alt det du har brug for. LigoWave er ikke Cisco, men er bestemt heller ikke et lavprisprodukt. LigoWave giver en utrolig balance mellem kvalitet og prisniveau. Vi betragter LigoWave som en af de mest innovative producenter i Europa og vi er stolte over at LigoWave har udvidet samarbejdet med os.\"</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">&rdquo;Hos LigoWave udtaler salgsdirekt&oslash;r Evaldas Velavicius, &ldquo;Collaboration with Cloud Router will allow us to be more dedicated and efficient in how we work with channel partners in Denmark so as to meet project quality demands and to provide a top-level service.&rdquo;</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><br /><strong><span style=\"color: #333333;\">LigoWaves partner program</span></strong><br /><span style=\"color: #333333;\">LigoWave Partner program: <span style=\"color: #0000ff;\"><a title=\"Download LigoWave Partner program\" href=\"https://drive.google.com/file/d/1u7HRZfmG-2tkOmM-McdmAUvsnqYFohju/view\" target=\"_blank\"><span style=\"color: #0000ff;\">Hent som PDF</span></a></span></span><br /><span style=\"color: #333333;\">LigoWaves partner web: <span style=\"color: #0000ff;\"><a title=\"Bes&oslash;g LigoWave Partner portal\" href=\"https://www.ligowave.com/ligowave-partner-program\" target=\"_blank\"><span style=\"color: #0000ff;\">https://www.ligowave.com/ligowave-partner-program</span></a></span></span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><strong><br />Om LigoWave</strong></span><br /><span style=\"color: #333333;\">LigoWave er en af verdens f&oslash;rende producenter med hoveds&aelig;de i Europa indenfor WiFi, punkt-til-punkt og multipunkt tr&aring;dl&oslash;se l&oslash;sninger, med st&aelig;rk fokus p&aring; at levere robuste og h&oslash;jtydende produkter. LigoWave har allerede et unikt marked hos danske installat&oslash;rer og antenneforeninger. Blandt andet med tr&aring;dl&oslash;se dataoverf&oslash;rsel til kameraoverv&aring;gning med h&oslash;j driftssikkerhed og h&oslash;jtydende WiFi hos antenneforeninger. Ydermere er der flere af internetudbyderne, der er i gang med at implementere LigoWaves tr&aring;dl&oslash;se l&oslash;sninger i landomr&aring;der til etablering af WTTx internettilslutninger. For yderligere information om LigoWave bes&oslash;g venligst www.ligowave.com</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><strong><br />Om Cloud Router</strong></span><br /><span style=\"color: #333333;\">Vi er passionerede mennesker, med dybe r&oslash;dder i tr&aring;dl&oslash;s datakommunikation. Vi leverer tr&aring;dl&oslash;se internet- og netv&aelig;rksl&oslash;sninger til professionelt brug. Som kunde kan du leve dine ambitioner ud i en international kultur sammensat af topprofessionelle folk, som deler passionen for datakommunikation. Vi har fokus p&aring; at skabe gode og us&aelig;dvanlige resultater sammen med vores kunder, som har de strengeste krav til investering, kvalitet og driftssikkerhed. Cloud Routers kompetence er en sammens&aelig;tning af specialister, der har 20 &aring;rs erfaring indenfor tr&aring;dl&oslash;s kommunikation, samt velkendte producenter af tr&aring;dl&oslash;se l&oslash;sninger. Det betyder at vi arbejder t&aelig;t sammen med vores producenter og teknologi-partnere, og deltager i udviklingen af nye produkter. Det g&oslash;r at vi kan levere skr&aelig;ddersyede l&oslash;sninger til vores kunder.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">L&aelig;s ogs&aring; nyheden p&aring; <a title=\"Bes&oslash;g LigoWave news\" href=\"https://www.ligowave.com/news-events/ligowave-is-strengthening-its-partnership-with-cloud-router\" target=\"_blank\">LigoWaves web</a></span></p>\r\n<p><span style=\"color: #333333;\">For yderligere information kontakt os venligst p&aring; salg[@]cloudrouter.dk</span></p>',	'Cloud Router og LigoWave er nu klar med et nyt partnerprogram og med et udvidet lager til forhandlere i Danmark. Det overordnede fælles mål er, at vores forhandlere i Danmark skal opnå endnu større succes med at sælge, installere og servicere LigoWave produkter. Læs videre...',	'',	'https://lh6.googleusercontent.com/wuQnanW-BGOwtAasIGfs-xkmRC7080kbWFqY1VmgFWf2zBprlS1RAXkOUUFO-UugCqOxNs3euTP6SlWom8id=w3000-h1717',	'',	1,	1),
(17,	'Teknisk support på timebasis',	'2019-06-27',	'<p style=\"text-align: justify;\"><span style=\"color: #333333;\">Fra 01. juli 2019 afregnes <span>teknisk support&nbsp;</span>p&aring; timebasis. Vores teknisk support indeb&aelig;rer, at vi altid str&aelig;ber efter at levere den bedste kvalitet til en fornuftig pris. Som en vidensbaseret datakommunikationsvirksomhed, kan Cloud Router anses for at v&aelig;re et uvildigt kompetencehus, uanset om du er en slutkunde eller installat&oslash;r. </span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><br /></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\">Timepriserne kan ses p&aring; dokumentet</span> <span style=\"color: #0000ff;\"><a title=\"Teknisk support\" href=\"https://drive.google.com/file/d/17tKjPIkrw_auyHhqVQrya3lycAES59bk/view?usp=drive_open\" target=\"_blank\"><span style=\"color: #0000ff;\">Teknisk support</span></a><span style=\"color: #333333;\">.</span></span></p>',	'Fra 01. juli 2019 afregnes timeforbrug vedr. teknisk support på timebasis',	'',	'',	'',	1,	1);
